            $"搜索快照的模拟器已经释放：{_releasedBy ?? "unknown"}:{_releasedAtLine}。");

    public bool HasSimulator => _simulator != null;

    private MandatoryEndTurn? _mandatoryEndTurn;
    private sealed class MandatoryEndTurn(object owner, int turn, int actionCount, SimulationSnapshot result)
    {
        public object Owner { get; } = owner;
        public int Turn { get; } = turn;
        public int ActionCount { get; } = actionCount;
        public SimulationSnapshot Result { get; } = result;
    }
    internal bool HasMandatoryEndTurnForTesting => _mandatoryEndTurn is not null;
    internal void SaveMandatoryEndTurn(object owner, int turn, int actionCount, SimulationSnapshot result)
    {
        var previous = Interlocked.Exchange(ref _mandatoryEndTurn, new(owner, turn, actionCount, result));
        previous?.Result.ReleaseSimulator();
    }
    internal SimulationSnapshot? TakeMandatoryEndTurn(object owner, int turn, int actionCount, bool requireComplete = false)
    {
        var saved = Volatile.Read(ref _mandatoryEndTurn);
        if (saved is null || !ReferenceEquals(saved.Owner, owner) || saved.Turn != turn
            || saved.ActionCount != actionCount || !HasSimulator) return null;
        // A caller collecting adaptive choice checkpoints may use only a complete,
        // reliable result. Pending choices retain the original discovery/capture path.
        if (requireComplete && (saved.Result.BoundaryReason != SearchBoundaryReason.None
            || saved.Result.HasRisk)) return null;
        return ReferenceEquals(Interlocked.CompareExchange(ref _mandatoryEndTurn, null, saved), saved)
            ? saved.Result : null;
    }


    public void ReleaseSimulator(
        [CallerMemberName] string caller = "",
        [CallerLineNumber] int line = 0)
    {
        Interlocked.Exchange(ref _mandatoryEndTurn, null)?.Result.ReleaseSimulator();
        _simulator = null;
        _releasedBy = caller;
        _releasedAtLine = line;
    }
}

