using CombatSolver.Engine.Common;
using CombatSolver.Engine.InCombat.Simulation;
using MegaCrit.Sts2.Core.Combat;
using MegaCrit.Sts2.Core.Entities.Cards;

namespace CombatSolver;

internal sealed partial class CombatBeamSolver
{
    private object _mandatoryEndTurnOwner = new();
    private sealed class MandatoryEndTurnCounters
    {
        public int Probes, Prunes, Rejected, Saved;
        public int Waves, ParallelNodes;
    }
    private MandatoryEndTurnCounters _mandatoryEndTurnCounters = new();
    private int _mandatoryEndTurnProbes => Volatile.Read(ref _mandatoryEndTurnCounters.Probes);
    private int _mandatoryEndTurnPrunes => Volatile.Read(ref _mandatoryEndTurnCounters.Prunes);
    private int _mandatoryEndTurnRejected => Volatile.Read(ref _mandatoryEndTurnCounters.Rejected);
    private Action<SearchNode>? _mandatoryEndTurnJobObserverForTesting = null;
    internal bool DisableMandatoryEndTurnBoundForTesting { get; init; }

    private bool CanProbeMandatoryEndTurn(SearchNode node)
    {
        if (DisableMandatoryEndTurnBoundForTesting || !root.CanCertifyForcedEndTurnHealing
            || _hasGrowthTargets || root.InitialGrowthRewards.Total != 0 || policy.RelicTargets.Count != 0
            || _theftPolicy == SolverTheftPolicy.PreserveResources
            || _potionStrategy.HasForcedDirectives
            || node.IsTerminal || node.Snapshot.HasRisk || !node.Snapshot.HasSimulator
            || node.BoundaryReason != SearchBoundaryReason.None
            || node.Snapshot.StrategyGoalCount != 0 || node.Snapshot.StrategyGoalHpCredit != 0
            || node.Cycle is not null || node.CycleProbeLease is not null || node.CycleExitProbe is not null
            || node.CycleExitObservation is not null || node.PendingCycleExitObservation is not null
            || node.OrderedMutationLineage is not null || node.OrderedMutationRetentionLease is not null
            || node.CrossTurnProbe is not null || node.PowerCommitment is not null
            || !CanUseSharedPotionTier(ExplicitPotionUseCount(node), _maximumPotionUses,
                _forceAllPotionsDisabled, _potionPolicy, _potionStrategy.HasForcedDirectives))
            return false;
        var simulator = (CombatPredictionSimulator)node.Snapshot.Simulator;
        var combat = (SimulatedCombatState)simulator.State.CombatState;
        var state = simulator.State.GetPlayerCombatState(_player);
        if (!simulator.IsInProgress || simulator.HasPendingChoice || state.Phase != PlayerTurnPhase.Play)
            return false;
        foreach (var card in state.Hand.Cards)
            if (card.HasKeyword(simulator.State, CardKeyword.Sly)
                || combat.CanPlayCard(simulator, card))
                return false;
        return MandatoryEndTurnHealing(node.Snapshot) != int.MaxValue;
    }

    private int MandatoryEndTurnHealing(SimulationSnapshot snapshot)
        => snapshot.HasSimulator && !snapshot.HasRisk
            ? StrategicHpRecoveryBound.ComponentHealingUpperBound(
                (CombatPredictionSimulator)snapshot.Simulator, _player,
                root.PostCombatRelicHeal.UnconditionalHeal + root.PostCombatRelicHeal.WoundedHeal,
                includePotionHealing: !_forceAllPotionsDisabled, maximumExplicitPotionUses: _maximumPotionUses,
                potionStrategy: _potionStrategy, effectivePotionPolicy: _potionPolicy,
                useReviewedSources: true)
            : int.MaxValue;

    private bool ProbeMandatoryEndTurn(SearchNode node, int ceiling, bool alreadyCertified = false)
    {
        _mandatoryEndTurnJobObserverForTesting?.Invoke(node);
        if (!alreadyCertified && !CanProbeMandatoryEndTurn(node)) return false;
        cancellationToken.ThrowIfCancellationRequested();
        Interlocked.Increment(ref _mandatoryEndTurnCounters.Probes);
        using var capture = new RoundReplayCheckpointCapture(node);
        SimulationSnapshot? forward = ReplayAction(node,
            new PlanAction(PlanActionKind.EndTurn, node.Turn), roundCheckpointCapture: capture);
        try
        {
            int healing = MandatoryEndTurnHealing(forward);
            if (capture.HasCheckpoint || forward.BoundaryReason != SearchBoundaryReason.None
                || forward.HasRisk || forward.PlayerDead || forward.AllEnemiesDead
                || forward.DeathSaveUseCount != 0 || healing == int.MaxValue)
            {
                Interlocked.Increment(ref _mandatoryEndTurnCounters.Rejected);
                return false;
            }
            if (StrategicHpLowerBound(forward, _strategicBossHpRelief, healing) > ceiling)
            {
                Interlocked.Increment(ref _mandatoryEndTurnCounters.Prunes);
                return true;
            }
            node.Snapshot.SaveMandatoryEndTurn(_mandatoryEndTurnOwner, node.Turn, node.ActionCount, forward);
            forward = null;
            Interlocked.Increment(ref _mandatoryEndTurnCounters.Saved);
            return false;
        }
        finally { forward?.ReleaseSimulator(); }
    }

    private List<SearchNode> ApplyMandatoryEndTurnBound(List<SearchNode> retained, int ceiling)
    {
        if (!root.CanCertifyForcedEndTurnHealing || DisableMandatoryEndTurnBoundForTesting
            || retained.Count == 0 || _hasGrowthTargets || policy.RelicTargets.Count != 0
            || root.InitialGrowthRewards.Total != 0 || _theftPolicy == SolverTheftPolicy.PreserveResources
            || _potionStrategy.HasForcedDirectives)
            return retained;
        bool[] cuts = new bool[retained.Count];
        List<SearchNode> pending = [];
        List<int> indices = [];
        var executor = _run.ActiveParallelExpansion;
        // No parent may be forked by two probe jobs. Aliases preserve the serial path.
        var seen = new HashSet<CombatPredictionSimulator>(ReferenceEqualityComparer.Instance);
        bool independent = true;
        for (int index = 0; index < retained.Count; index++)
        {
            SearchNode node = retained[index];
            if (!CanProbeMandatoryEndTurn(node)) continue;
            pending.Add(node);
            indices.Add(index);
            independent &= seen.Add((CombatPredictionSimulator)node.Snapshot.Simulator);
        }
        if (executor is not null && pending.Count >= 2 && independent)
        {
            _run.CheckpointPruneMetadata?.Invoke("mandatory_end_turn");
            for (int start = 0; start < pending.Count;)
            {
                long reserve = StandPatProbeAllocationReserve();
                _run.EnsurePruneMemory?.Invoke(reserve);
                int count = Math.Min(executor.DegreeOfParallelism, ResolveStandPatBatchSize(
                    pending.Count - start, policy.MemoryPressureSignal.RemainingBytes, reserve));
                var batch = start == 0 && count == pending.Count
                    ? pending : pending.GetRange(start, count);
                Interlocked.Increment(ref _mandatoryEndTurnCounters.Waves);
                Interlocked.Add(ref _mandatoryEndTurnCounters.ParallelNodes, count);
                bool[] results = executor.EvaluateMandatoryEndTurnProbes(batch, ceiling);
                for (int index = 0; index < count; index++)
                    cuts[indices[start + index]] = results[index];
                start += count;
            }
            _run.CheckpointPruneMetadata?.Invoke("after_mandatory_end_turn");
        }
        else
            for (int index = 0; index < pending.Count; index++)
                cuts[indices[index]] = ProbeMandatoryEndTurn(pending[index], ceiling, alreadyCertified: true);
        List<SearchNode>? bounded = null;
        for (int index = 0; index < retained.Count; index++)
        {
            if (cuts[index])
            {
                bounded ??= retained.GetRange(0, index);
                _run.PrimaryIncumbentBranchesPruned++;
            }
            else bounded?.Add(retained[index]);
        }
        return bounded ?? retained;
    }

    private void EmitMandatoryEndTurnDiagnostics()
    {
        if (root.CanCertifyForcedEndTurnHealing)
            policy.Diagnostics.Info($"[CombatSolver/Test] MANDATORY_END_TURN_BOUND "
                + $"probes={_mandatoryEndTurnProbes} pruned={_mandatoryEndTurnPrunes} "
                + $"rejected={_mandatoryEndTurnRejected} saved={_mandatoryEndTurnCounters.Saved} "
                + $"waves={_mandatoryEndTurnCounters.Waves} parallel_nodes={_mandatoryEndTurnCounters.ParallelNodes}");
    }
}

