internal sealed partial class CombatBeamSolver
{
    internal sealed record MandatoryFixtureResult(IReadOnlyList<SearchNode> Prefix, SimulationSnapshot Later, int Pruned);

    internal static MandatoryFixtureResult MandatoryFixtureForTesting(CombatRootSnapshot root,
        SolverDisplayNames names, BattleDamageSnapshot damage, SearchPolicySnapshot policy, bool regen,
        Action<string> mark)
