        if (!winner.IsTerminal || winner.Snapshot.HasRisk || winner.Snapshot.PlayerDead
            || !solver.TightenPrimarySearchIncumbentAtTurnLayer([winner], 0)
            || solver._primaryIncumbent is not { } incumbent)
            throw new InvalidOperationException("Complete qualified incumbent was not built.");
        List<SearchNode> prefix = [];
        SearchNode bad = opening;
        foreach (string id in new[] { "BLOODLETTING", "STORM_OF_STEEL", "SHIV", "SHIV", "SHIV", "SHIV" })
            prefix.Add(bad = Play(bad, id));
        mark("bad-prefix");
        if (!solver.CanProbeMandatoryEndTurn(bad) || bad.Snapshot.HasRisk || bad.IsTerminal)
            throw new InvalidOperationException("Fixture did not reach a forced EndTurn.");
        var control = new CombatBeamSolver(root, names, damage, policy, maximumPotionUses: 0,
            primaryIncumbent: incumbent) { DisableMandatoryEndTurnBoundForTesting = true };
        if (control.ApplyPrimaryIncumbentBound([bad]).Count != 1)
            throw new InvalidOperationException("Old bound already pruned the mandatory branch.");
        int keep = solver.ApplyPrimaryIncumbentBound([bad]).Count;
        if (keep != (regen ? 1 : 0) || solver._mandatoryEndTurnPrunes != (regen ? 0 : 1))
            throw new InvalidOperationException($"Unexpected cut: keep={keep} pruned={solver._mandatoryEndTurnPrunes} regen={regen} incumbent={incumbent.StrategicHpDeficit}.");
        mark("bound-checked");
        solver.VerifyRankedMandatoryWorkersForTesting(bad, opening, regen, incumbent.StrategicHpDeficit);
        mark("actual-sixteen-lane-wave-and-ordered-holes");
        if (!regen) VerifyRankedMandatoryDrainForTesting(root, names, damage, policy, bad);
        mark("error-and-cancellation-drain");
        if (regen && (!bad.Snapshot.HasMandatoryEndTurnForTesting
            || bad.Snapshot.TakeMandatoryEndTurn(new object(), bad.Turn, bad.ActionCount) is not null
            || bad.Snapshot.TakeMandatoryEndTurn(solver._mandatoryEndTurnOwner, bad.Turn + 1, bad.ActionCount) is not null
            || bad.Snapshot.TakeMandatoryEndTurn(solver._mandatoryEndTurnOwner, bad.Turn, bad.ActionCount + 1) is not null))
            throw new InvalidOperationException("Owned-result identity guards failed.");
        var end = new PlanAction(PlanActionKind.EndTurn, bad.Turn);
