internal sealed partial class CombatBeamSolver
{
    private SearchNode ForkMandatoryNodeForTesting(SearchNode template)
    {
        var snapshot = Snapshot(template.Snapshot.Simulator.Fork(), template.Turn, template.ActionCount,
            template.Snapshot.ShufflesCrossed, template.BoundaryReason,
            ((ForkableSet<uint>)template.Snapshot.ProcessedEnemyDeaths).Fork());
        return new SearchNode(template.Action, template.ActionCount, template.PotionCount,
            template.PotionStrategicCost, template.Turn, template.Traits, template.FutureSoldHp,
            snapshot.Score, snapshot.StateKey, snapshot.HasRisk, snapshot.BoundaryReason,
            template.IsTerminal, template.Parent, snapshot, template.CombatProgress);
    }

    private void VerifyRankedMandatoryWorkersForTesting(SearchNode template, SearchNode playable,
        bool shouldKeep, int ceiling)
    {
        var nodes = Enumerable.Range(0,16).Select(_ => ForkMandatoryNodeForTesting(template)).ToList();
        SearchNode guard = ForkMandatoryNodeForTesting(playable);
        var ordered = new List<SearchNode>(nodes);
        ordered.Insert(0,guard); ordered.Insert(9,guard);
        string Before(SearchNode n) => ContinuationStamp.CapturePredicted(_player, n.Snapshot.Simulator,
            n.Turn, root.Forecast, root.StartTurnNumber).StateText;
        string[] before = nodes.Select(Before).ToArray();
        int probes = _mandatoryEndTurnProbes, cuts = _mandatoryEndTurnPrunes;
        int waves = _mandatoryEndTurnCounters.Waves;
        try
        {
            using (var executor = new ParallelExpansionExecutor(this,16))
            {
                var retained = ApplyMandatoryEndTurnBound(ordered,ceiling);
                if (_mandatoryEndTurnProbes-probes !=16 || _mandatoryEndTurnPrunes-cuts!=(shouldKeep?0:16)
                    || _mandatoryEndTurnCounters.Waves-waves!=1
                    || retained.Count!=(shouldKeep?18:2)
                    || (shouldKeep ? !retained.SequenceEqual(ordered,ReferenceEqualityComparer.Instance)
                        : !ReferenceEquals(retained[0],guard) || !ReferenceEquals(retained[1],guard)))
                    throw new InvalidOperationException("Sixteen real proof lanes or retained holes differ.");
                for (int i=0;i<nodes.Count;i++)
                {
                    var node=nodes[i];
                    if (Before(node)!=before[i] || node.Snapshot.HasMandatoryEndTurnForTesting!=shouldKeep)
                        throw new InvalidOperationException("Probe changed its parent or cached ownership.");
                    if (shouldKeep)
                    {
                        var worker=CreateExpansionWorker();
                        var evaluated=worker.EvaluatePreparedEndTurn(node,new object());
                        if (evaluated.Batch is null || evaluated.Batch.EndTurns.Count!=1
                            || node.Snapshot.HasMandatoryEndTurnForTesting)
                            throw new InvalidOperationException("Actual end-turn worker did not consume its result once.");
                        using (evaluated.Batch)
                        {
                            var child=evaluated.Batch.EndTurns.Single();
                            if (child.Snapshot.HasRisk || child.Snapshot.PlayerDead
                                || child.BoundaryReason!=SearchBoundaryReason.None)
                                throw new InvalidOperationException("Strict cached replay produced unreliable state.");
                        }
                    }
                }
            }
        }
        finally
        {
            foreach(var node in nodes)node.Snapshot.ReleaseSimulator();
            guard.Snapshot.ReleaseSimulator();
        }
        if(nodes.Any(n=>n.Snapshot.HasMandatoryEndTurnForTesting))
            throw new InvalidOperationException("Forward result survived parent release.");
    }

    private static void VerifyRankedMandatoryDrainForTesting(CombatRootSnapshot root,
        SolverDisplayNames names,BattleDamageSnapshot damage,SearchPolicySnapshot policy,SearchNode template)
    {
        foreach(bool cancel in new[]{false,true})
        {
            using var cancellation=new CancellationTokenSource(TimeSpan.FromSeconds(20));
            using var entered=new CountdownEvent(16);
            var solver=new CombatBeamSolver(root,names,damage,policy,cancellation.Token,maximumPotionUses:0);
            var nodes=Enumerable.Range(0,16).Select(_=>solver.ForkMandatoryNodeForTesting(template)).ToList();
            solver._mandatoryEndTurnJobObserverForTesting=node=>
            {
                entered.Signal();
                if(!entered.Wait(TimeSpan.FromSeconds(5)))
                    throw new InvalidOperationException("Actual wave did not dispatch sixteen lanes.");
                if(ReferenceEquals(node,nodes[0]))
                {
                    if(cancel)cancellation.Cancel();
                    else throw new InvalidOperationException("expected mandatory worker failure");
                }
            };
            try
            {
                using var executor=new ParallelExpansionExecutor(solver,16);
                bool propagated=false;
                try {executor.EvaluateMandatoryEndTurnProbes(nodes,0);}
                catch(OperationCanceledException) when(cancel && cancellation.IsCancellationRequested)
                {propagated=true;}
                catch(InvalidOperationException error) when(!cancel && error.Message=="expected mandatory worker failure")
                {propagated=true;}
                if(!propagated || entered.CurrentCount!=0 || executor._activeMandatoryEndTurnWorkers!=0)
                    throw new InvalidOperationException("Worker error/cancellation was hidden or wave not drained.");
            }
            finally{foreach(var node in nodes)node.Snapshot.ReleaseSimulator();}
        }
    }
}
